def pacha(b, velho, novo):
    if velho == novo:
        return b
    pos = 0
    while True:
        i = b.find(velho, pos)
        if i < 1: break
        if b[i-1] == len(velho):
            nb = bytes([len(novo)]) + novo
            b = b[:i-1] + nb + b[i+len(velho):]
            pos = i - 1 + len(nb)
        else:
            pos = i + 1
    return b

