# ===== ESTADO PERSISTENTE (Render e volatil: cada deploy apaga o disco) =====
# look/slots ficam salvos no branch 'estado' do repo (API contents do GitHub).
import urllib.request as _ureq_g
_ESTADO_TOKEN = os.environ.get("MONTROY_GIT_TOKEN") or ""
_ESTADO_REPO = os.environ.get("MONTROY_GIT_REPO") or "borgesadriana688-eng/rzim-lobby143"
_ESTADO_BRANCH = "estado"
_ESTADO_HDR = {"Authorization": "Bearer " + _ESTADO_TOKEN, "Accept": "application/vnd.github+json",
               "User-Agent": "montroy-estado", "Content-Type": "application/json"}

def _estado_get(fname):
    if not _ESTADO_TOKEN:
        return None
    try:
        _r = _ureq_g.Request("https://api.github.com/repos/%s/contents/%s?ref=%s" % (_ESTADO_REPO, fname, _ESTADO_BRANCH), headers=_ESTADO_HDR)
        _d = json.loads(_ureq_g.urlopen(_r, timeout=8).read())
        return json.loads(base64.b64decode(_d["content"]))
    except Exception:
        return None

def _estado_put(fname, obj):
    if not _ESTADO_TOKEN:
        return
    for _i in (1, 2):
        _sha = None
        try:
            _r = _ureq_g.Request("https://api.github.com/repos/%s/contents/%s?ref=%s" % (_ESTADO_REPO, fname, _ESTADO_BRANCH), headers=_ESTADO_HDR)
            _d = json.loads(_ureq_g.urlopen(_r, timeout=8).read())
            _sha = _d.get("sha")
            if json.loads(base64.b64decode(_d["content"])) == obj:
                return
        except Exception:
            pass
        try:
            _b = {"message": "estado: %s" % fname, "branch": _ESTADO_BRANCH,
                  "content": base64.b64encode(json.dumps(obj).encode()).decode()}
            if _sha:
                _b["sha"] = _sha
            _r = _ureq_g.Request("https://api.github.com/repos/%s/contents/%s" % (_ESTADO_REPO, fname),
                                 data=json.dumps(_b).encode(), method="PUT", headers=_ESTADO_HDR)
            _ureq_g.urlopen(_r, timeout=8).read()
            return
        except Exception:
            continue

def _look_load():
    """Carrega looks equipados do disco ou do repo (sobrevive a redeploy)."""
    _n = 0
    try:
        with open(_LOOK_FILE) as _f:
            for _u, _ids in json.load(_f).items():
                _LOOK[str(_u)] = list(_ids or [])
        _n = len(_LOOK)
    except Exception:
        pass
    if not _n:
        _d = _estado_get("look.json")
        if _d:
            for _u, _ids in _d.items():
                _LOOK[str(_u)] = list(_ids or [])
            _n = len(_LOOK)
            print("[LOOK] restaurado do repo: %d uid(s)" % _n, flush=True)
    print("[LOOK] carregados %d uid(s)" % _n, flush=True)

def _look_save():
    try:
        with open(_LOOK_FILE, "w") as _f:
            json.dump(_LOOK, _f)
    except Exception:
        pass
    _th.Thread(target=_estado_put, args=("look.json", dict(_LOOK)), daemon=True).start()

_look_load()

def _rv(b, i):
    v = 0; sh = 0
    while i < len(b):
        x = b[i]; i += 1
        v |= (x & 0x7f) << sh; sh += 7
        if not x & 0x80: break
    return v, i

def _wv(n):
    out = b""
    while True:
        b = n & 0x7F; n >>= 7
        out += bytes([b | (0x80 if n else 0)])
        if not n: break
    return out

def _parse_equip(body):
    """pedido ChangeClothes: f1=uid, f2=ids empacotados, f3=slot. Retorna (uid, ids, slot) ou None."""
    try:
        i = 0; uid = None; ids = []; slot = 5
        while i < len(body):
            tag, i = _rv(body, i)
            fn, wt = tag >> 3, tag & 7
            if wt == 0:
                v, i = _rv(body, i)
                if fn == 1: uid = v
                elif fn == 3: slot = v
            elif wt == 2:
                ln, i = _rv(body, i)
                data = body[i:i+ln]; i += ln
                if fn == 2:
                    j = 0
                    while j < len(data):
                        v, j = _rv(data, j); ids.append(v)
            else:
                break
        if uid and ids: return uid, ids, slot
    except Exception:
        pass
    return None

def _build_equip_resp(uid, ids, slot):
    packed = b"".join(_wv(x) for x in ids)
    inner = b"\x08" + _wv(uid) + b"\x10\x01\x18" + _wv(slot) + b"\x22" + _wv(len(packed)) + packed + b"\x2a\x05\x08\x00\x10\x9e\x11\x30\x01"
    return b"\x0a" + _wv(len(inner)) + inner

IPTAG_ICON_URL = ("https://base44.app/api/apps/6ad692e379c2a6e77cbe0722/files/mp/public/"
                  "6ad692e379c2a6e77cbe0722/59e3e9118_iptag_verificado.png")

def _iptag_config():
    """Selos de verificado (IPTag): config servida local com o selo do montroy.
    Estrutura do desc: {1: ip_tag_icon(url), 2: is_hide} + base {3: id, 4: nome}."""
    def _wv(n):
        out = b""
        while True:
            x = n & 0x7f; n >>= 7
            out += bytes([x | (0x80 if n else 0)])
            if not n: return out
    def _s(f, v): return bytes([f << 3 | 2]) + _wv(len(v)) + v
    def _v(f, n): return bytes([f << 3]) + _wv(n)
    desc = (_s(1, IPTAG_ICON_URL.encode()) + _v(2, 0)
            + _v(3, 1) + _s(4, b"Montroy Verificado") + _v(5, 1))
    return _s(1, desc)      # ip_tag_config (repeated): 1 entrada

def _broadcast_montroy():
    """Letreiro do lobby (LoginGetBroadcast): mesma ESTRUTURA byte a byte da
    resposta real que funcionava (156B), so com o texto do Bryan no lugar.
    Strings novas + timestamps renovados, resto preservado."""
    def _rdv(b, i):
        r = 0; sh = 0
        while True:
            x = b[i]; i += 1
            r |= (x & 0x7f) << sh; sh += 7
            if not x & 0x80: return r, i
    def _wrv(n):
        out = b""
        while True:
            x = n & 0x7f; n >>= 7
            out += bytes([x | (0x80 if n else 0)])
            if not n: return out
    MARQUEE = "Bem vindo ao montroy Server, desenvolvido por Brayan".encode()
    SISMSG = "Servidor montroy \xe2\x80\x94 desenvolvido por Brayan".encode()
    agora = int(time.time() * 1000)

    def _campos(b):
        out = []; i = 0
        while i < len(b):
            try: k, i = _rdv(b, i)
            except Exception: return None
            f, w = k >> 3, k & 7
            if w == 0:
                v, i = _rdv(b, i); out.append((f, 'v', v))
            elif w == 2:
                l, i = _rdv(b, i)
                if i + l > len(b): return None
                out.append((f, 'b', b[i:i+l])); i += l
            elif w == 5: out.append((f, 'f', b[i:i+4])); i += 4
            elif w == 1: out.append((f, 'd', b[i:i+8])); i += 8
            else: return None
        return out

    def _reb(b):
        fs = _campos(b)
        if fs is None: return None
        out = b""
        for f, t, v in fs:
            if t == 'v':
                if v > 10**11: v = agora        # timestamp em ms -> renova
                out += _wrv((f << 3)) + _wrv(v)
            elif t == 'b':
                sub = _reb(v)
                if sub is not None:
                    out += _wrv((f << 3) | 2) + _wrv(len(sub)) + sub
                else:
                    nv = v
                    if v == b"MID 5 PRIVATE - PRIVATE SERVER \xe2\x80\xa2 KEY DURATION: EXPIRADA - ATIVE SUA CONTA":
                        nv = MARQUEE
                    elif v == b"Criado por ZRIDER, GUSTAVINNM, WELL":
                        nv = SISMSG
                    out += _wrv((f << 3) | 2) + _wrv(len(nv)) + nv
            elif t == 'f': out += _wrv((f << 3) | 5) + v
            else: out += _wrv((f << 3) | 1) + v
        return out

    try:
        d = DATA.get("/LoginGetBroadcast") or {}
        base_b = base64.b64decode(d.get("resp_b64") or "")
        nb = _reb(base_b)
        if nb: return nb
    except Exception:
        pass
    return base_b

def _splash_montroy():
    """LoginGetSplash: sem imagem de banner MID5 e sem link. Item de anuncio so com texto MONTROY."""
    def s(f, v):
        v = v.encode() if isinstance(v, str) else v
        return bytes([f << 3 | 2]) + _wv(len(v)) + v
    def n(f, v):
        return bytes([f << 3]) + _wv(v)
    item = (s(1, "pt-BR") + n(2, 0) + s(3, "MONTROY") + s(9, WELCOME_MSG)
            + n(10, 1791506588) + n(11, 2147483000) + s(12, "BR") + n(13, 820000063) + n(14, 0) + n(19, 1))
    wrap = s(1, item)
    return s(1, wrap)


