def _fp_majorlogin(pb):
    """Fingerprint do aparelho no MajorLogin: campo 19 (Google|uuid) ou 57."""
    try:
        i = 0
        f19 = f57 = None
        while i < len(pb):
            tag, i = _rv(pb, i)
            fn, wt = tag >> 3, tag & 7
            if wt == 0:
                v, i = _rv(pb, i)
            elif wt == 2:
                l, i = _rv(pb, i)
                v = pb[i:i+l]; i += l
                if fn == 19 and not f19:
                    f19 = v.decode(errors="replace")
                elif fn == 57 and not f57:
                    f57 = v.decode(errors="replace")
            elif wt == 5:
                i += 4
            elif wt == 1:
                i += 8
            else:
                break
        if f19:
            return f19
        if f57:
            return "aid:" + f57
    except Exception:
        pass
    return ""

