def _look_atual(uid=None):
    """ids do look equipado por ESTE uid (ChangeClothes). Cada jogador tem o
    seu; quem nunca equipou recebe o padrao (nunca o look de outro jogador)."""
    if uid is None and _UID_CTX is not None:
        uid = getattr(_UID_CTX, "uid", None)
    with _LOOK_LOCK:
        if uid is not None and str(uid) in _LOOK:
            return _LOOK[str(uid)]
    return list(_LOOK_PADRAO)

def _patch_look(b):
    """Aplica o look equipado nas respostas que carregam a lista de ids
    (PersonalShow, ChooseSlots, ChooseShow: lista packed com prefixo de tamanho)."""
    old = LOOK_CAPTURADO
    if old not in b:
        return b
    ids = _look_atual()
    new = b"".join(_wv(x) for x in ids)
    i = b.index(old)
    pre = b[i-1]
    if pre != len(old):
        return b
    return b[:i-1] + bytes([len(new)]) + new + b[i+len(old):]

def _personal_show(base_resp):
    """GetPlayerPersonalShow: aplica o look equipado pelo jogador."""
    return _patch_look(base_resp)

def _uid_slots(pb):
    """ChooseSlots: 0a<len><lista...> + campo(s) finais; o uid do jogador vem
    como varint no fim (ex.: 8788f0b203 -> 101000007). Retorna str ou '0'."""
    try:
        i = 0
        tag, i = _rv(pb, i)
        if (tag >> 3) == 1 and (tag & 7) == 2:
            ln, i = _rv(pb, i)
            i += ln
            while i < len(pb):
                tag, i = _rv(pb, i)
                if (tag & 7) == 0:
                    v, i = _rv(pb, i)
                    if v > 10**6:
                        return str(v)
                elif (tag & 7) == 2:
                    l, i = _rv(pb, i); i += l
                else:
                    break
    except Exception:
        pass
    return "0"

def _req_uid(body):
    """Extrai o campo 1 (uid) do pedido protobuf (SelectProfile/UnlockProfile)."""
    try:
        i = 0
        while i < len(body):
            tag, i = _rv(body, i)
            fn, wt = tag >> 3, tag & 7
            if wt == 0:
                v, i = _rv(body, i)
                if fn == 1:
                    return v
            elif wt == 2:
                ln, i = _rv(body, i)
                i += ln
            else:
                return None
    except Exception:
        pass
    return None

def _troca_uid_resp(resp, novo_uid):
    """Troca o uid (campo 1 do item interno) da resposta de perfil pelo id que o jogo pediu.
    Mantem todo o resto identico a captura (skins, slot, etc.)."""
    try:
        if resp and resp[0] == 0x0A:
            _ln, i = _rv(resp, 1)
            if i < len(resp) and resp[i] == 0x08:
                _antigo, j = _rv(resp, i + 1)
                novo = _wv(novo_uid)
                return resp[:i + 1] + novo + resp[j:]
    except Exception:
        pass
    return resp


# ---- AES: os pedidos do cliente 1.70 vem cifrados (chave do http_aes.txt) ----
try:
    from Crypto.Cipher import AES as _AES_C
    _AES_KEY = bytes.fromhex("482a4a694f706a7a425e364a664c6e4a")
    _AES_IV = bytes.fromhex("6b6e56705621264d79372371304d6948")
except Exception:
    _AES_C = None

def _dec_req(body):
    """Decifra pedido AES-CBC do cliente (perfil/skin). So se for bloco de 16
    e o resultado parecer protobuf; senao devolve o corpo original."""
    if not body or len(body) % 16 or _AES_C is None:
        return body
    try:
        p = _AES_C.new(_AES_KEY, _AES_C.MODE_CBC, _AES_IV).decrypt(body)
        if p and p[0] in (0x08, 0x0A, 0x10, 0x12, 0x18, 0x1A, 0x22, 0x2A):
            return p
    except Exception:
        pass
    return body


