# grava pares pedido/resposta em capture.jsonl e devolve a resposta intacta.
# Ativa via env: PROXY_PANEL, PROXY_GAME, (opcional) PROXY_REMOTE_VERSION.
PROXY_PANEL = os.environ.get("PROXY_PANEL") or ""
PROXY_GAME = os.environ.get("PROXY_GAME") or ""
PROXY_REMOTE_VERSION = os.environ.get("PROXY_REMOTE_VERSION") or ""
PROXY_ON = bool(PROXY_GAME)
_PROXY_CAPTURE_FILE = "capture.jsonl"
_PROXY_LOCK = _th.Lock()
_PROXY_COOKIES = {}

PROXY_PANEL_RELAY = os.environ.get("PROXY_PANEL_RELAY") or ""

def _panel_fwd(tgt, environ, body):
    """Envia pedido do painel via relay Base44 (o IP do Render e bloqueado
    pelo painel de referencia com 400+HTML). Devolve (st, ct, resp) ou None
    para cair no envio direto."""
    if not PROXY_PANEL_RELAY:
        return None
    d = _jc.dumps({"target": tgt,
                   "method": environ.get("REQUEST_METHOD", "GET"),
                   "ctype": environ.get("HTTP_CONTENT_TYPE") or "application/json",
                   "body": base64.b64encode(body or b"").decode()}).encode()
    req = _urc.Request(PROXY_PANEL_RELAY, data=d,
                       headers={"Content-Type": "application/json",
                                "User-Agent": "rzim-bridge/1.0"})
    try:
        r = _urc.urlopen(req, timeout=90)
        j = _jc.loads(r.read())
        st = int(j.get("status") or 502)
        return st, (j.get("ctype") or "application/octet-stream"), base64.b64decode(j.get("resp_b64") or "")
    except Exception as e:
        print("[PONTE] relay do painel falhou: %s" % e, flush=True)
        return None

_ORIG_CERT_MD5 = b"9fb8f21073d34e50d8cfcec891b5e511"   # cert do APK original de referencia
_HYB_CERT_MD5 = b"ffd6314a83f267ac4f9407fd2e5a0480"   # cert do APK do cliente local (uber debug)

def _proxy_game_body(body):
    """O servidor de referencia so aceita o cliente 1.70 com o certificado do
    APK original: reescreve o corpo AES (mesmos tamanhos, padding intacto),
    trocando a versao 1.43.0 -> 1.70.0 e o MD5 do certificado."""
    if not body or len(body) % 16 or _AES_C is None:
        return body
    try:
        p = _AES_C.new(_AES_KEY, _AES_C.MODE_CBC, _AES_IV).decrypt(body)
        if b"1.43.0" in p or _HYB_CERT_MD5 in p:
            p = p.replace(b"1.43.0", b"1.70.0")
            p = p.replace(_HYB_CERT_MD5, _ORIG_CERT_MD5)
            return _AES_C.new(_AES_KEY, _AES_C.MODE_CBC, _AES_IV).encrypt(p)
    except Exception:
        pass
    return body

def _proxy_fwd(target, environ, body, use_cookies=True):
    """Repassa o pedido ao servidor alvo e devolve (status, ctype, resp)."""
    req = _urc.Request(target, data=body if body else None,
                       method=environ.get("REQUEST_METHOD", "GET"))
    for h in ("Content-Type", "User-Agent", "Accept"):
        v = environ.get("HTTP_" + h.upper().replace("-", "_"))
        if v:
            req.add_header(h, v)
    # repassa os cabecalhos proprios do jogo (X-*, ReleaseVersion etc.):
    # carregam o ticket de sessao do /Login que o servidor principal exige
    # — sem eles GetLoginData responde vazio.
    _skip = {"host", "content-length", "connection", "accept-encoding",
             "content-type", "user-agent", "accept", "cookie", "origin",
             "referer", "x-forwarded-for", "x-forwarded-host"}
    for hk, hv in environ.items():
        if not hk.startswith("HTTP_"):
            continue
        hn = hk[5:].replace("_", "-")
        if hn.lower() in _skip:
            continue
        try:
            if not req.has_header(hn):
                req.add_header(hn, hv)
        except Exception:
            pass
    # rotas do painel de referencia vao SEM cookies: sessao antiga acumulada
    # fazia o painel responder 400 com a pagina HTML de erro
    if use_cookies and _PROXY_COOKIES:
        req.add_header("Cookie", "; ".join("%s=%s" % kv for kv in _PROXY_COOKIES.items()))
    try:
        r = _urc.urlopen(req, timeout=90)
        st, hdrs, resp = r.status, r.headers, r.read()
    except _urc.HTTPError as e:
        st, hdrs, resp = e.code, e.headers, e.read()
    except Exception as e:
        return 502, "text/plain", str(e).encode()[:200]
    if use_cookies:
        try:
            for sc in (hdrs.get_all("Set-Cookie") or []):
                kv = sc.split(";", 1)[0]
                if "=" in kv:
                    k, v = kv.split("=", 1)
                    _PROXY_COOKIES[k.strip()] = v.strip()
        except Exception:
            pass
    return st, (hdrs.get("Content-Type") or "application/octet-stream"), resp

def _proxy_save(rota, req, st, ct, resp, hdrs=None):
    """Grava o par pedido/resposta (a captura que vira o jogo do servidor)."""
    line = _jc.dumps({"t": int(time.time()), "rota": rota, "status": st,
                      "ctype": ct, "req_b64": base64.b64encode(req).decode(),
                      "resp_b64": base64.b64encode(resp).decode(),
                      "hdrs": hdrs or {}})
    try:
        with _PROXY_LOCK:
            with open(_PROXY_CAPTURE_FILE, "a") as _f:
                _f.write(line + "\n")
    except Exception:
        pass
    _capture("PROXY " + rota, base64.b64encode(req)[:60].decode(), resp[:80].hex(),
             "len=%d st=%d" % (len(resp), st))

_PAIR_CACHE = {"v": "", "t": 0.0}

def _proxy_current_pair():
    """Busca o pair_id atual da pagina de login do painel de referencia.
    E rotativo e expira em segundos: SEMPRE busca fresco (o cache serve so
    de fallback se a pagina nao responder)."""
    now = time.time()
    tgt = PROXY_PANEL.rstrip("/") + "/login"
    # tenta via relay (Render e bloqueado direto) e depois direto
    for via_rel in (PROXY_PANEL_RELAY, ""):
        try:
            html = ""
            if via_rel:
                d = _jc.dumps({"target": tgt, "method": "GET",
                               "ctype": "text/html", "body": ""}).encode()
                req = _urc.Request(via_rel, data=d,
                                  headers={"Content-Type": "application/json"})
                j = _jc.loads(_urc.urlopen(req, timeout=60).read())
                html = base64.b64decode(j.get("resp_b64") or b"").decode("utf-8", "replace")
            else:
                req = _urc.Request(tgt, headers={"User-Agent": "Dalvik/2.1.0"})
                html = _urc.urlopen(req, timeout=60).read().decode("utf-8", "replace")
            m = re.search(r"REVENGER_PAIR_ID\s*=\s*'([^']+)'", html)
            if m:
                _PAIR_CACHE.update({"v": m.group(1), "t": now})
                print("[PONTE] pair_id atual: %s (via %s)" % (m.group(1)[:10], "relay" if via_rel else "direto"), flush=True)
                return m.group(1)
        except Exception as e:
            print("[PONTE] busca pair falhou (%s)" % e, flush=True)
    return _PAIR_CACHE.get("v") or ""

def _proxy_handle(rota, environ, body):
    """True se atendeu (resposta ja enviada); False se a rota e local."""
    p = rota.split("?")[0]
    # rotas locais em modo ponte: ver/sinal, downloads, hot-update, admin
    if (p in ("/", "/health", "/_logs", "/_captures") or
            p.startswith(("/signal/live", "/live/", "/downloads/", "/_logs", "/_captures"))):
        return False
    # dialogo de login estilo Facebook (tela de login do jogo em WebView)
    # e do painel, nao do jogo -> vai pro host do painel de referencia
    _fbdlg = bool(__import__("re").fullmatch(r"(/v\d+(\.\d+)?)?/dialog/oauth", p)) or \
              p.rstrip("/") in ("/login.php", "/v9.0/login.php", "/dialog/oauth/")
    if _fbdlg:
        # tela de login do jogo (WebView do dialogo FB): serve a pagina de
        # login LOCAL; os /api/captcha, /api/register e /api/login que ela
        # chama vao pela ponte pro painel de referencia, entao a conta
        # criada e REAL la. Sem isso o WebView mostrava "Not implemented!!".
        try:
            import conta_pv as _cpv
            return 200, "text/html; charset=utf-8", _cpv.LOGIN_HTML
        except Exception:
            pass
        tgt = PROXY_PANEL.rstrip("/") + p
    # servidor principal do jogo (URL devolvida no MajorLogin)
    if p.startswith("/signal/main"):
        tgt = "https://api.pautavero.com/signal/main" + p[len("/signal/main"):]
    # /oauth/* (exchange do MSDK) tambem e do PAINEL de referencia
    elif p.startswith("/api/") or p.startswith("/access") or p.startswith("/oauth/"):
        tgt = PROXY_PANEL.rstrip("/") + p
    else:
        tgt = PROXY_GAME.rstrip("/") + p
    # o MSDK do jogo manda o exchange form-encoded, mas o painel de
    # referencia so aceita JSON (senao responde "Bad Request").
    if p.startswith("/oauth/token/") and body and not body.lstrip().startswith(b"{"):
        try:
            import urllib.parse as _up
            _fd = dict(_up.parse_qsl(body.decode("utf-8")))
            body = json.dumps(_fd).encode("utf-8")
            environ["CONTENT_TYPE"] = "application/json"
            environ["HTTP_CONTENT_TYPE"] = "application/json"
        except Exception:
            pass
    # o painel de referencia rejeita (HTTP 400) pair_id desconhecido
    # (o "rzim-pair" da nossa pagina local). Remove do registro/login.
    if p in ("/api/register", "/api/login") and body:
        try:
            _j = json.loads(body.decode("utf-8"))
            if isinstance(_j, dict) and "pair_id" in _j:
                _par = _proxy_current_pair()
                if _par:
                    _j["pair_id"] = _par
                else:
                    del _j["pair_id"]
                body = json.dumps(_j).encode("utf-8")
        except Exception:
            pass
    q = environ.get("QUERY_STRING") or ""
    if q:
        tgt += "?" + q
    _painel = tgt.startswith(PROXY_PANEL.rstrip("/"))
    if _painel:
        _rr = _panel_fwd(tgt, environ, body)
        if _rr is not None:
            st, ct, resp = _rr
        else:
            st, ct, resp = _proxy_fwd(tgt, environ, body, use_cookies=False)
    else:
        st, ct, resp = _proxy_fwd(tgt, environ, _proxy_game_body(body))
    # o MajorLogin devolve a URL do servidor principal (api.pautavero.com/
    # signal/main); o cliente conectaria DIRETO, contornando a ponte e o
    # mesmo filtro de versao/certificado. Redireciona pro nosso host de
    # 17 chars (mesmo tamanho da URL original, 37 bytes).
    if b"https://api.pautavero.com/signal/main" in resp:
        resp = resp.replace(b"https://api.pautavero.com/signal/main",
                            b"https://rzim.onrender.com/signal/main")
        print("[PONTE] URL principal reescrita -> rzim.onrender.com", flush=True)
    print("[PONTE] %s -> %s | HTTP %s | %d bytes" % (p, tgt, st, len(resp)), flush=True)
    _proxy_save(p, body, st, ct, resp,
                hdrs={k[5:].replace("_", "-"): v for k, v in environ.items()
                      if k.startswith("HTTP_")})
    return st, ct, resp

def application(environ, start_response):
    rota = environ.get("PATH_INFO", "")
    _reqbody = b""
    try:
        n = int(environ.get("CONTENT_LENGTH") or 0)
        if n: _reqbody = environ["wsgi.input"].read(n)
    except Exception:
        pass
    _pb = _dec_req(_reqbody)
    if rota.startswith("/signal/live/integrity/"):
        # Guarda de integridade do APK MID5 (challenge/proof). Emulado local:
        # aceita o APK modificado (rzim) que o original deles rejeitaria.
        if rota.rstrip("/").endswith("/challenge"):
            _nonce = base64.urlsafe_b64encode(__import__("secrets").token_bytes(32)).decode().rstrip("=")
            _b = json.dumps({"ok": True, "nonce": _nonce,
                             "issued_at": int(time.time() * 1000),
                             "expires_in": 90}).encode()
            print("[INTEGRITY] challenge ok nonce=%s..." % _nonce[:8], flush=True)
            start_response("200 OK", [("Content-Type", "application/json; charset=utf-8"),
                                     ("Content-Length", str(len(_b)))])
            return [_b]
        if rota.rstrip("/").endswith("/proof"):
            _now = int(time.time() * 1000)
            _b = json.dumps({"ok": True, "issued_at": _now,
                             "valid_until": _now + 30 * 24 * 3600 * 1000}).encode()
            print("[INTEGRITY] proof ok", flush=True)
            start_response("200 OK", [("Content-Type", "application/json; charset=utf-8"),
                                     ("Content-Length", str(len(_b)))])
            return [_b]
        start_response("404 Not Found", [("Content-Type", "application/json"), ("Content-Length", "33")])
        return [b'{"ok":false,"error":"unknown_route"}']
    if PROXY_ON:
        _pr = _proxy_handle(rota, environ, _reqbody)
        if _pr is not False:
            st, ct, resp = _pr
            start_response("%d %s" % (st, "OK" if st < 400 else "ERROR"),
                           [("Content-Type", ct), ("Content-Length", str(len(resp)))])
            return [resp]
        if rota.startswith("/_captures"):
            try:
                with open(_PROXY_CAPTURE_FILE, "rb") as _f:
                    _b = _f.read()
            except Exception:
                _b = b""
            start_response("200 OK", [("Content-Type", "application/json"), ("Content-Length", str(len(_b)))])
            return [_b]
    if rota == "/_captures":
        try:
            with open(_PROXY_CAPTURE_FILE, "rb") as _f:
                _b = _f.read()
        except Exception:
            _b = b""
        start_response("200 OK", [("Content-Type", "application/json"), ("Content-Length", str(len(_b)))])
        return [_b]
    _capture(rota, _reqbody[:400].hex(), _pb[:400].hex(), "req len=%d" % len(_reqbody))
    # MODO LOCAL: o cliente chama /signal/main/X no servidor principal (rzim).
    # Tira o prefixo para casar com as respostas embutidas (DATA) e a logica local.
    if rota.startswith("/signal/main/"):
        rota = "/" + rota[len("/signal/main/"):]
    if rota == "/GetIPTagConfig":
        b = _iptag_config()
        start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
        return [b]
    if rota == "/LoginGetBroadcast":
        b = _broadcast_montroy()
        start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
        return [b]
    if rota == "/ChooseSlots" and _pb:
        # pedido: campo 1 (packed) = lista crua de slots (emotes)
        try:
            _i = 0
            _tag, _i = _rv(_pb, _i)
            if (_tag >> 3) == 1 and (_tag & 7) == 2:
                _ln, _i = _rv(_pb, _i)
                _lista = _pb[_i:_i+_ln]
                _uid_s = str(getattr(_UID_CTX, "uid", None) or _TOK_UID.get(_tok) or 0)
                with _SLOTS_LOCK:
                    _SLOTS[_uid_s] = _lista
                _slots_save()
                print("[SLOTS] uid=%s lista=%dB %s" % (_uid_s, len(_lista), _lista.hex()[:40]), flush=True)
        except Exception:
            _lista = None
        _b = resposta("/ChooseSlots")[0] or b""
        # troca a lista ecoada no template (campo 7 packed) pela lista nova
        try:
            import base64 as _b64cs
            _old = None
            with _SLOTS_LOCK:
                _old = _SLOTS.get("captura_antiga")
            _resp = _b64cs.b64decode(DATA["/ChooseSlots"]["resp_b64"])
            # a lista antiga = slice apos \x3a<comprimento> na resposta capturada
            _k = _resp.find(b"\x3a")
            _lnb = _resp[_k+1]
            _old = _resp[_k+2:_k+2+_lnb]
            if _old and _old in _b:
                _new = _lista if _lista else _old
                _k2 = _b.index(_old)
                _pre = _b[_k2-1]
                # comprimento externo (campo 1) tb muda
                _dif = len(_new) - len(_old)
                _b = _b[:_k2-1] + bytes([_pre + _dif]) + _new + _b[_k2+len(_old):]
                # ajusta o comprimento do campo 1 externo (primeiros 2 bytes \x0a<len>)
                if _b[0] == 0x0a:
                    _b = bytes([0x0a, _b[1] + _dif]) + _b[2:]
        except Exception as _e:
            print("[SLOTS] erro eco: %s" % _e, flush=True)
        _b = _patch_look(_b)
        start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(_b)))])
        return [_b]
    if rota == "/LoginGetSplash":
        b = _splash_montroy()
        start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
        return [b]
    if rota.startswith("/live/ABHotUpdates/"):
        # Emulacao do CDN de hot-update (o oficial responde 403 p/ 1.43)
        rest = rota[len("/live/ABHotUpdates/"):]
        if rest.startswith("android/"):
            parts = rest[len("android/"):].split("/")
            # FIX 19/10: caminhos de recurso OPCIONAL tem mais segmentos
            # (ex.: android/optional/optionalclothres/0/fileinfo). O parser
            # antigo lia so os 2 primeiros ("optional"=versao,
            # "optionalclothres"=arquivo) e devolvia 404 pro fileinfo ->
            # cliente 1.70 quebrava no lobby (TXT_ sem localizacao, skins
            # nao equipam, personagem invisivel). Agora fileinfo/versioninfo
            # sao reconhecidos no ULTIMO segmento, em qualquer profundidade.
            last = parts[-1] if parts else ""
            if last == "versioninfo":
                # exatamente o que o OBB local do cliente tem: 1.70.0, contador 0
                b = b"1.70.0\r\n0"
                start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
                return [b]
            if last == "fileinfo":
                if parts and parts[0] == "optional":
                    # recurso opcional: manifesto VAZIO = "nada novo pra baixar"
                    # -> cliente segue com os assets do OBB local, sem erro
                    b = b""
                else:
                    # fileinfo exato do OBB (extraido do main.2019114971.obb) ->
                    # cliente conclui que esta 100% atualizado, nao baixa nada
                    b = base64.b64decode(ABHOT_FILEINFO_B64)
                start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
                return [b]
        # pedido de arquivo de recurso: 404 (fica visivel na captura p/ eu servir depois)
        start_response("404 Not Found", [("Content-Type", "text/plain"), ("Content-Length", "0")])
        return [b""]
    # uid do jogador deste pedido -> look/slots separados por jogador.
    # PersonalShow/ChangeClothes trazem o uid no corpo; ChooseSlots nao, entao
    # o uid vem do token de sessao (Authorization), associado ao 1o pedido com uid.
    _UID_CTX.uid = None
    _tok = (environ.get("HTTP_AUTHORIZATION") or "")[-40:]
    try:
        if rota == "/ChangeClothes": _UID_CTX.uid = (_parse_equip(_pb) or (None,))[0]
        elif rota in ("/GetPlayerPersonalShow", "/SelectProfile", "/UnlockProfile"): _UID_CTX.uid = _req_uid(_pb)
        if _UID_CTX.uid and _tok and rota in ("/ChangeClothes", "/GetPlayerPersonalShow"):
            _TOK_UID[_tok] = int(_UID_CTX.uid)
        elif _tok and _tok in _TOK_UID:
            _UID_CTX.uid = _TOK_UID[_tok]
    except Exception:
        _UID_CTX.uid = None
    if rota in ("/ChangeClothes", "/GetBackpack", "/GetPlayerPersonalShow", "/SelectProfile", "/UnlockProfile"):
        print("[BODY] %s len=%d hex=%s dec=%s" % (rota, len(_reqbody), _reqbody[:300].hex(), _pb[:300].hex()), flush=True)
    if rota == "/ChangeClothes":
        pe = _parse_equip(_pb)
        if pe:
            uid, ids, slot = pe
            with _LOOK_LOCK:
                _LOOK[str(uid)] = ids
                _look_save()
            b = _build_equip_resp(uid, ids, slot)
            print("[EQUIP] uid=%s ids=%s slot=%s" % (uid, ids, slot), flush=True)
            _capture(rota, "uid=%s ids=%s slot=%s" % (uid, ids, slot), b.hex(), "resp-equip")
            start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
            return [b]
    if rota in ("/SelectProfile", "/UnlockProfile"):
        req_uid = _req_uid(_pb)
        print("[PERFIL] %s pedido uid=%s hex=%s dec=%s" % (rota, req_uid, _reqbody.hex(), _pb.hex()), flush=True)
        cap_uid = _perfil_replay_uid(rota)
        if cap_uid:
            b = _perfil_capture_b(rota)
            if req_uid and req_uid != cap_uid:
                b = _troca_uid_resp(b, req_uid)
                print("[PERFIL] %s respondendo uid do JOGO (%s), captura era %s" % (rota, req_uid, cap_uid), flush=True)
            _capture(rota, "req_uid=%s cap_uid=%s" % (req_uid, cap_uid), b.hex(), "resp-perfil")
            start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
            return [b]
        if req_uid:
            b = _perfil_resp(req_uid, unlock=(rota == "/UnlockProfile"))
            start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
            return [b]
    body, ctype = resposta_controle(rota, environ)
    if body is None:
        body, ctype = resposta(rota)
        if rota == "/MajorLogin" and body is not None:
            # conta do aparelho: uid + token proprios (banco separado por jogador)
            _fp = _fp_majorlogin(_pb)
            _c = _conta(_fp) if _fp else None
            if _c:
                body = body.replace(b"\x08" + _wv(_CONTAS_UID_INICIAL), b"\x08" + _wv(_c["uid"]))
                body = body.replace(_CONTAS_TOKEN_FIXO.encode(), _c["token"].encode())
                _TOK_UID[_c["token"]] = _c["uid"]
                print("[CONTAS] MajorLogin fp=%s... -> uid=%d" % (_fp[:24], _c["uid"]), flush=True)
        if rota in ("/ChooseEmote", "/ChooseShow", "/ChooseBanner", "/ChooseHeadPic") and body is not None:
            _u = getattr(_UID_CTX, "uid", None)
            if _u:
                _eq_registra(rota, _pb, _u)
                _eco = None
                if rota in ("/ChooseBanner", "/ChooseHeadPic"):
                    try:
                        _i2 = 0
                        _t2, _i2 = _rv(_pb, _i2)
                        if (_t2 >> 3) == 1:
                            _eco, _ = _rv(_pb, _i2)
                    except Exception:
                        _eco = None
                body = _eq_aplica_resposta(body, _u, "choose", _eco)
                body = _patch_look(body)
        if rota == "/GetPlayerPersonalShow" and body is not None:
            _u = getattr(_UID_CTX, "uid", None)
            body = _personal_show(body)
            if _u:
                body = _eq_aplica_resposta(body, _u, "pesso")
            _capture(rota, "", body[:400].hex(), "resp-show len=%d" % len(body))
        if rota == "/GetBackpack" and body is not None:
            body = _troca_avatar_snapshot(body)
            body = _aplica_slots_backpack(body, getattr(_UID_CTX, "uid", None))
            body = _eq_aplica_backpack(body, getattr(_UID_CTX, "uid", None))
            _capture(rota, "", body[:400].hex(), "resp-backpack len=%d" % len(body))
    if body is None and rota in ("/SelectProfile", "/UnlockProfile"):
        uid = _perfil_replay_uid(rota)
        if uid:
            b = _perfil_resp(uid, unlock=(rota == "/UnlockProfile"))
            start_response("200 OK", [("Content-Type", "application/octet-stream"), ("Content-Length", str(len(b)))])
            return [b]
    if body is None:
        if rota == "/app/info/get":
            body = json.dumps({"client_log": False, "status": 0, "maintenance": False, "version": "1.70.0",
                "game_server": GAME_PUBLIC_ADDR, "update_url": "",
                "notice": {"title": "Rzim Server", "content": "Lobby 1.43", "show": True}}, separators=(",", ":")).encode()
            ctype = "application/json"
        else:
            try:
                open(LOG_UNK, "a").write("%s %s %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), environ.get("REQUEST_METHOD"), rota))
            except Exception:
                pass
            body, ctype = GENERIC, "application/octet-stream"
    start_response("200 OK", [("Content-Type", ctype), ("Content-Length", str(len(body)))])
    return [body]

app = application
